#ifndef OPENFS_LQCD_RANGE_H
#define OPENFS_LQCD_RANGE_H
#include <chrono>
#include <cstdio>
#include <openacc.h>
#include <nvtx3/nvToolsExt.h>

// Use the upstream benchmark's existing instrumentation hooks without changing
// the numerical code. Preinclude this header only for the benchmark main file.
#define FAPP_MACROS_H_INCLUDED
static std::chrono::steady_clock::time_point openfs_started;
static void openfs_start(const char* name) {
  acc_wait_all();
  nvtxRangePushA(name);
  openfs_started = std::chrono::steady_clock::now();
}
static void openfs_stop() {
  acc_wait_all();
  const auto end = std::chrono::steady_clock::now();
  nvtxRangePop();
  std::fprintf(stderr, "OPENFS_TRAJECTORY_SECONDS=%.9f\n",
    std::chrono::duration<double>(end - openfs_started).count());
}
#define START_FAPP(name, number, level) openfs_start(name)
#define STOP_FAPP(name, number, level) openfs_stop()
#endif

#ifndef OPENFS_LQCD_PHASES_H
#define OPENFS_LQCD_PHASES_H
#include <chrono>
#include <cstdio>
#include <openacc.h>
namespace openfs {
using Clock = std::chrono::steady_clock;
static Clock::time_point started, previous;
static double init_seconds, main_seconds;
static void begin() { started = previous = Clock::now(); }
static void compute() {
  acc_wait_all();
  auto now = Clock::now();
  init_seconds = std::chrono::duration<double>(now - previous).count();
  previous = now;
}
static void finish() {
  acc_wait_all();
  auto now = Clock::now();
  main_seconds = std::chrono::duration<double>(now - previous).count();
  previous = now;
}
static void end() {
  auto now = Clock::now();
  std::fprintf(stderr,
    "OPENFS_PHASES init=%.9f compute=%.9f final=%.9f total=%.9f\n",
    init_seconds, main_seconds, std::chrono::duration<double>(now - previous).count(),
    std::chrono::duration<double>(now - started).count());
}
}
#endif

#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cuda_runtime_api.h>
#include <nvtx3/nvToolsExt.h>

// Single MPI rank only. Profile and normal runs use identical phase boundaries.
extern "C" void openfs_phase_(const int *phase) {
  using Clock = std::chrono::steady_clock;
  static Clock::time_point started, previous;
  static double elapsed[3];
  static int expected = 0;
  if (*phase != expected || *phase < 0 || *phase > 3) std::abort();
  if (*phase > 0 && cudaDeviceSynchronize() != cudaSuccess) std::abort();
  const auto now = Clock::now();
  if (*phase == 0) {
    started = previous = now;
    nvtxRangePushA("openfs-total");
  } else {
    elapsed[*phase - 1] = std::chrono::duration<double>(now - previous).count();
    previous = now;
    nvtxRangePop();
  }
  const char *names[] = {"initialization", "compute", "finalization"};
  if (*phase < 3) nvtxRangePushA(names[*phase]);
  else {
    nvtxRangePop();
    std::printf("OPENFS_INITIALIZATION_SECONDS=%.9f\nOPENFS_COMPUTE_SECONDS=%.9f\n"
                "OPENFS_FINALIZATION_SECONDS=%.9f\nOPENFS_TOTAL_SECONDS=%.9f\n",
                elapsed[0], elapsed[1], elapsed[2],
                std::chrono::duration<double>(now - started).count());
  }
  ++expected;
}

"""Exact, fail-closed instrumentation of pinned upstream Fortran sources."""
import argparse
from pathlib import Path


def insert(path, replacements):
    text = path.read_text()
    for before, after in replacements:
        if text.count(before) != 1:
            raise ValueError(f"Ambiguous phase boundary in {path}: {before}")
        text = text.replace(before, after)
    path.write_text(text)


def instrument(application, source):
    if application == "genesis":
        insert(source / "src/spdyn/spdyn.fpp", [
            ("    call timer(TimerTotal, TimerOn)", "    call openfs_phase(0)\n    call timer(TimerTotal, TimerOn)"),
            ("    call timer(TimerDynamics, TimerOn)", "    call openfs_phase(1)\n    call timer(TimerDynamics, TimerOn)"),
            ("    call timer(TimerDynamics, TimerOff)", "    call timer(TimerDynamics, TimerOff)\n    call openfs_phase(2)"),
            ("    call timer(TimerTotal, TimerOff)", "    call timer(TimerTotal, TimerOff)\n    call openfs_phase(3)"),
        ])
    else:
        for directory, filename, iteration in (
            ("gs", "main_dft.f90", "GS"), ("rt", "main_tddft.f90", "RT")
        ):
            insert(source / "src" / directory / filename, [
                ("call timer_begin(LOG_TOTAL)", "call openfs_phase(0)\ncall timer_begin(LOG_TOTAL)"),
                (f"call timer_begin(LOG_{iteration}_ITERATION)", f"call openfs_phase(1)\ncall timer_begin(LOG_{iteration}_ITERATION)"),
                (f"call timer_end(LOG_{iteration}_ITERATION)", f"call timer_end(LOG_{iteration}_ITERATION)\ncall openfs_phase(2)"),
                ("call timer_end(LOG_TOTAL)", "call timer_end(LOG_TOTAL)\ncall openfs_phase(3)"),
            ])


if __name__ == "__main__":
    p = argparse.ArgumentParser()
    p.add_argument("application", choices=("genesis", "salmon"))
    p.add_argument("source", type=Path)
    a = p.parse_args()
    instrument(a.application, a.source)

